// Rejects anything not signed by Convex in the last 5 minutes. The signature
// covers the raw bytes, because re-serializing parsed JSON could change them.
const crypto = require('crypto');
const MAX_AGE_MS = 5 * 60 * 1000;

const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not set');

const { headers } = $input.first().json;
const timestamp = headers['x-lendloop-timestamp'] ?? '';
const signature = headers['x-lendloop-signature'] ?? '';
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
const received = /^[0-9a-f]{64}$/.test(signature) ? Buffer.from(signature, 'hex') : Buffer.alloc(32);
const isFresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() - Number(timestamp)) <= MAX_AGE_MS;
const valid = crypto.timingSafeEqual(expected, received) && isFresh;

return [{ json: { valid, payload: valid ? JSON.parse(raw) : null } }];

// Mock channel: replace this node with Email, Slack, or similar to send for real.
// A real provider should get eventId as its idempotency key, since Convex
// retries until it sees a success and may occasionally deliver twice.
const maskEmail = (email) => email.replace(/^(.).*(@.*)$/, '$1***$2');

const { eventId, event, recipient, toolName, startDate, endDate } = $json.payload;
const subjects = {
  'request.created': `New request to borrow your ${toolName}`,
  'request.approved': `Your request for the ${toolName} was approved`,
  'request.declined': `Your request for the ${toolName} was declined`,
  'request.cancelled': `A request for the ${toolName} was cancelled`,
  'request.returned': `The ${toolName} was marked returned`,
  'request.closed': `Your loan of the ${toolName} was closed by an admin`,
};
const notification = {
  channel: 'mock',
  eventId,
  to: maskEmail(recipient.email),
  subject: subjects[event] ?? `Update on the ${toolName}`,
  dates: `${startDate} to ${endDate}`,
};
console.log('[LendLoop notification]', JSON.stringify(notification));
return [{ json: notification }];
